1	import { runScenario, type Scenario } from "./claim-office.js";
2	
3	const readStdin = async (): Promise<string> => {
4	  const chunks: Buffer[] = [];
5	  for await (const chunk of process.stdin) {
6	    chunks.push(chunk as Buffer);
7	  }
8	  return Buffer.concat(chunks).toString("utf8");
9	};
10	
11	const main = async (): Promise<void> => {
12	  const scenario = JSON.parse(await readStdin()) as Scenario;
13	  process.stdout.write(JSON.stringify(runScenario(scenario)));
14	};
15	
16	await main();
17

1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Scenario {
6	  customer: Customer;
7	  steps: Step[];
8	}
9	
10	export type Step = QuoteStep | ClaimStep;
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Item {
18	  type: string;
19	  material?: string;
20	  enchantment?: number;
21	  cursed?: boolean;
22	}
23	
24	export interface ClaimStep {
25	  op: "claim";
26	  policy: number;
27	  incident: Incident;
28	}
29	
30	export interface Incident {
31	  cause: string;
32	  damages: Damage[];
33	}
34	
35	export interface Damage {
36	  itemType: string;
37	  amount: number;
38	}
39	
40	export type Result = QuoteResult | ClaimResult;
41	
42	export interface QuoteResult {
43	  premium: number;
44	}
45	
46	export interface ClaimResult {
47	  payout: number;
48	  remainingCap: number;
49	}
50	
51	export interface ScenarioResult {
52	  results: Result[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	const FIRST_INSURANCE_SURCHARGE_RATE = 1 / 10;
57	
58	// What a single item of each type is worth to the MHPCO: what it costs to
59	// insure, and what it is insured for. Keeping the two figures side by side
60	// makes this the one place that says which item types exist at all.
61	interface ItemTypeRates {
62	  basePremium: number;
63	  insuranceValue: number;
64	}
65	
66	const ITEM_TYPE_RATES: Record<string, ItemTypeRates> = {
67	  sword: { basePremium: 100, insuranceValue: 1000 },
68	  amulet: { basePremium: 60, insuranceValue: 600 },
69	  staff: { basePremium: 80, insuranceValue: 800 },
70	  potion: { basePremium: 40, insuranceValue: 400 },
71	  rune: { basePremium: 25, insuranceValue: 250 },
72	  moonstone: { basePremium: 25, insuranceValue: 250 },
73	};
74	
75	const LOYALTY_YEARS_THRESHOLD = 2;
76	const LOYALTY_DISCOUNT_RATE = 2 / 10;
77	const FOLLOW_UP_DISCOUNT_RATE = 15 / 100;
78	const CURSE_SURCHARGE_RATE = 1 / 2;
79	const HIGH_ENCHANTMENT_THRESHOLD = 5;
80	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 3 / 10;
81	const BLOCK_SIZE = 3;
82	const BLOCK_BASE_PREMIUM = 60;
83	const DEDUCTIBLE = 100;
84	const CAP_MULTIPLIER = 2;
85	const REDUCED_REIMBURSEMENT_THRESHOLD = 8;
86	const REDUCED_REIMBURSEMENT_RATE = 1 / 2;
87	
88	// The MHPCO's price list is closed: anything not on it cannot be insured.
89	const ratesFor = (type: string): ItemTypeRates => {
90	  const rates = ITEM_TYPE_RATES[type];
91	  if (rates === undefined) {
92	    throw new Error(`the MHPCO does not insure items of type ${type}`);
93	  }
94	  return rates;
95	};
96	
97	const unitBasePremium = (type: string): number => ratesFor(type).basePremium;
98	
99	const countByType = (items: Item[]): Map<string, number> =>
100	  items.reduce(
101	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
102	    new Map<string, number>(),
103	  );
104	
105	// A building block of 3 alike components is offered at a special base premium.
106	const basePremiumForItemGroup = (type: string, count: number): number =>
107	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * unitBasePremium(type);
108	
109	const policyBasePremium = (items: Item[]): number =>
110	  [...countByType(items)].reduce(
111	    (total, [type, count]) => total + basePremiumForItemGroup(type, count),
112	    0,
113	  );
114	
115	// Premium-side enchantment rule (threshold 5), distinct from the claim-side
116	// reduced-reimbursement rule (threshold 8).
117	const qualifiesForHighEnchantmentSurcharge = (item: Item): boolean =>
118	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
119	
120	const surchargeRate = (item: Item): number =>
121	  (item.cursed ? CURSE_SURCHARGE_RATE : 0) +
122	  (qualifiesForHighEnchantmentSurcharge(item) ? HIGH_ENCHANTMENT_SURCHARGE_RATE : 0);
123	
124	// Item-specific modifiers apply to the affected item's own base premium, i.e.
125	// the unit price of its type — a block discount never shrinks a surcharge.
126	const itemSurcharge = (item: Item): number =>
127	  unitBasePremium(item.type) * surchargeRate(item);
128	
129	const itemSurcharges = (items: Item[]): number =>
130	  items.reduce((total, item) => total + itemSurcharge(item), 0);
131	
132	const isLongStanding = (customer: Customer): boolean =>
133	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
134	
135	// Policy-wide modifiers apply to the policy base premium only — never to the
136	// item surcharges. Net signed delta: a discount can outweigh the surcharge.
137	// Every quote is a first insurance for its items, regardless of customer
138	// history, so that surcharge always applies.
139	const policyAdjustmentRate = (
140	  customer: Customer,
141	  isFollowUpContract: boolean,
142	): number =>
143	  FIRST_INSURANCE_SURCHARGE_RATE -
144	  (isLongStanding(customer) ? LOYALTY_DISCOUNT_RATE : 0) -
145	  (isFollowUpContract ? FOLLOW_UP_DISCOUNT_RATE : 0);
146	
147	// Premiums round up, in the MHPCO's favour. The adjustment is added as a
148	// separate term rather than folded into a `base * 1.1` factor, which is not
149	// exact in binary floating point (100 * 1.1 === 110.00000000000001).
150	const quotePremium = (
151	  items: Item[],
152	  customer: Customer,
153	  isFollowUpContract: boolean,
154	): number => {
155	  const base = policyBasePremium(items);
156	  return Math.ceil(
157	    base +
158	      itemSurcharges(items) +
159	      base * policyAdjustmentRate(customer, isFollowUpContract) +
160	      PROCESSING_FEE,
161	  );
162	};
163	
164	const unitInsuranceValue = (type: string): number =>
165	  ratesFor(type).insuranceValue;
166	
167	// The total payout per policy is capped at twice the insurance sum. Premium
168	// modifiers never reach the insurance sum: it is the plain sum of the unit
169	// values of the insured items.
170	const insuranceSum = (items: Item[]): number =>
171	  items.reduce((sum, item) => sum + unitInsuranceValue(item.type), 0);
172	
173	// A policy created by a quote step, tracked so later claims can pay out
174	// against it. `remainingCap` shrinks as successive claims are settled.
175	interface Policy {
176	  items: Item[];
177	  remainingCap: number;
178	}
179	
180	const openPolicy = (items: Item[]): Policy => ({
181	  items,
182	  remainingCap: CAP_MULTIPLIER * insuranceSum(items),
183	});
184	
185	// State accumulated by the steps run so far. Later steps price and pay out
186	// against what earlier steps established, so each step reads the state it was
187	// run with and returns the state the next step should see.
188	interface ScenarioState {
189	  customer: Customer;
190	  contractsSoFar: number;
191	  // Keyed by the zero-based index of the quote step that created the policy.
192	  policies: Map<number, Policy>;
193	}
194	
195	// A step's outcome: what to report, and how the scenario stands afterwards.
196	interface StepOutcome {
197	  result: Result;
198	  state: ScenarioState;
199	}
200	
201	// Records a policy against the step index that identifies it, leaving the
202	// state it was given untouched.
203	const withPolicy = (
204	  state: ScenarioState,
205	  policyId: number,
206	  policy: Policy,
207	): ScenarioState => ({
208	  ...state,
209	  policies: new Map(state.policies).set(policyId, policy),
210	});
211	
212	const quote = (
213	  step: QuoteStep,
214	  state: ScenarioState,
215	  stepIndex: number,
216	): StepOutcome => ({
217	  result: {
218	    premium: quotePremium(step.items, state.customer, state.contractsSoFar > 0),
219	  },
220	  state: withPolicy(
221	    { ...state, contractsSoFar: state.contractsSoFar + 1 },
222	    stepIndex,
223	    openPolicy(step.items),
224	  ),
225	});
226	
227	// Claim-side enchantment rule (threshold 8), distinct from the premium-side
228	// high-enchantment surcharge (threshold 5).
229	const qualifiesForReducedReimbursement = (item: Item): boolean =>
230	  (item.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_THRESHOLD;
231	
232	// Damage to heavily enchanted items is reimbursed at 50 % of the damage amount.
233	const reimbursementRate = (item: Item): number =>
234	  qualifiesForReducedReimbursement(item) ? REDUCED_REIMBURSEMENT_RATE : 1;
235	
236	// A damage entry together with the specific insured item it was matched to.
237	interface MatchedDamage {
238	  damage: Damage;
239	  item: Item;
240	}
241	
242	// What a single damage entry entitles the claimant to, before the policy-wide
243	// cap is applied. A deductible applies per damage event, i.e. once per damaged
244	// item. Special clauses reduce the reimbursement first; the deductible comes
245	// off after.
246	const damageEntitlement = ({ damage, item }: MatchedDamage): number =>
247	  damage.amount * reimbursementRate(item) - DEDUCTIBLE;
248	
249	// Pairs each damage entry with a distinct insured item of the same type: two
250	// damages to "sword" refer to two different insured swords, not the same one
251	// twice. Instances of a type are consumed in the order they were insured.
252	const matchDamagesToItems = (
253	  insuredItems: Item[],
254	  damages: Damage[],
255	): MatchedDamage[] => {
256	  const unclaimed = [...insuredItems];
257	  return damages.map((damage) => {
258	    const index = unclaimed.findIndex((item) => item.type === damage.itemType);
259	    if (index === -1) {
260	      throw new Error(
261	        `the policy does not cover a damaged ${damage.itemType}`,
262	      );
263	    }
264	    return { damage, item: unclaimed.splice(index, 1)[0] };
265	  });
266	};
267	
268	// Reading a policy the scenario never opened is a programming error rather
269	// than a claimant's mistake, so this says so plainly instead of asserting the
270	// lookup succeeded and failing later with an incidental TypeError. Validating
271	// the claim step's policy index against the scenario is a separate concern,
272	// still to be specified.
273	const policyFor = (state: ScenarioState, policyId: number): Policy => {
274	  const policy = state.policies.get(policyId);
275	  if (policy === undefined) {
276	    throw new Error(`there is no policy ${policyId}`);
277	  }
278	  return policy;
279	};
280	
281	// The MHPCO does not reimburse a negative loss.
282	const rejectNegativeAmounts = (damages: Damage[]): void => {
283	  const negative = damages.find((damage) => damage.amount < 0);
284	  if (negative !== undefined) {
285	    throw new Error(
286	      `damage amount ${negative.amount} for ${negative.itemType} is negative`,
287	    );
288	  }
289	};
290	
291	// What the matched damages entitle the claimant to, before the policy-wide cap.
292	const claimEntitlement = (matchedDamages: MatchedDamage[]): number =>
293	  matchedDamages.reduce(
294	    (total, matched) => total + damageEntitlement(matched),
295	    0,
296	  );
297	
298	// The total payout per policy is capped: a claim gets at most what is left of
299	// the cap, and whatever it takes is no longer available to later claims. Both
300	// figures are derived here so they cannot drift apart.
301	const settleAgainstCap = (
302	  entitlement: number,
303	  remainingCap: number,
304	): ClaimResult => {
305	  // Payouts round down, in the MHPCO's favour. Rounding happens before the cap
306	  // is applied so that `remainingCap` is derived from the amount actually paid.
307	  const payout = Math.min(Math.floor(entitlement), remainingCap);
308	  return { payout, remainingCap: remainingCap - payout };
309	};
310	
311	const claim = (step: ClaimStep, state: ScenarioState): StepOutcome => {
312	  const policy = policyFor(state, step.policy);
313	  rejectNegativeAmounts(step.incident.damages);
314	  const matchedDamages = matchDamagesToItems(policy.items, step.incident.damages);
315	  const result = settleAgainstCap(
316	    claimEntitlement(matchedDamages),
317	    policy.remainingCap,
318	  );
319	  return {
320	    result,
321	    state: withPolicy(state, step.policy, {
322	      ...policy,
323	      remainingCap: result.remainingCap,
324	    }),
325	  };
326	};
327	
328	const runStep = (
329	  step: Step,
330	  state: ScenarioState,
331	  stepIndex: number,
332	): StepOutcome => {
333	  switch (step.op) {
334	    case "quote":
335	      return quote(step, state, stepIndex);
336	    case "claim":
337	      return claim(step, state);
338	  }
339	};
340	
341	// Where a scenario stands before any of its steps have run.
342	const initialState = (customer: Customer): ScenarioState => ({
343	  customer,
344	  contractsSoFar: 0,
345	  policies: new Map(),
346	});
347	
348	// The scenario part-way through: the results reported so far, and the state
349	// the next step will be run against.
350	interface ScenarioProgress {
351	  results: Result[];
352	  state: ScenarioState;
353	}
354	
355	// Each step is priced against the state the steps before it established, so
356	// the walk is sequential: fold the steps, threading the state from one to the
357	// next and collecting one result per step. The results array therefore mirrors
358	// the input steps in length and order.
359	export const runScenario = (scenario: Scenario): ScenarioResult => {
360	  const { results } = scenario.steps.reduce<ScenarioProgress>(
361	    ({ results, state }, step, stepIndex) => {
362	      const outcome = runStep(step, state, stepIndex);
363	      return { results: [...results, outcome.result], state: outcome.state };
364	    },
365	    { results: [], state: initialState(scenario.customer) },
366	  );
367	  return { results };
368	};
369

1	import { describe, it, expect } from "vitest";
2	import { execFile } from "node:child_process";
3	import { fileURLToPath } from "node:url";
4	
5	const CLI = fileURLToPath(new URL("./cli.ts", import.meta.url));
6	
7	interface CliRun {
8	  stdout: string;
9	  stderr: string;
10	  code: number;
11	}
12	
13	const runCli = (input: string): Promise<CliRun> =>
14	  new Promise((resolve) => {
15	    const child = execFile(
16	      "npx",
17	      ["tsx", CLI],
18	      (error, stdout, stderr) => {
19	        resolve({ stdout, stderr, code: error?.code === undefined ? 0 : Number(error.code) });
20	      },
21	    );
22	    child.stdin?.end(input);
23	  });
24	
25	describe("claim-office CLI", () => {
26	  it("reads a scenario from stdin and writes results to stdout", async () => {
27	    const scenario = {
28	      customer: { yearsWithMHPCO: 5 },
29	      steps: [
30	        {
31	          op: "quote",
32	          items: [
33	            { type: "amulet", material: "silver", enchantment: 2, cursed: false },
34	          ],
35	        },
36	        {
37	          op: "claim",
38	          policy: 0,
39	          incident: {
40	            cause: "fire",
41	            damages: [{ itemType: "amulet", amount: 200 }],
42	          },
43	        },
44	      ],
45	    };
46	
47	    const { stdout, code } = await runCli(JSON.stringify(scenario));
48	
49	    // premium: 60 base − 12 loyalty + 6 first insurance + 5 fee = 59
50	    // claim: 200 − 100 deductible = 100; cap 1200 − 100 = 1100
51	    expect(JSON.parse(stdout)).toEqual({
52	      results: [{ premium: 59 }, { payout: 100, remainingCap: 1100 }],
53	    });
54	    expect(code).toBe(0);
55	  });
56	
57	  it.todo("exits non-zero and writes to stderr when a quote has an unknown item type");
58	  it.todo("exits non-zero and writes to stderr when a claim is not covered by the policy");
59	  it.todo("writes no results to stdout when the scenario is rejected");
60	});
